components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid var(--color-ink);
  background: var(--color-ink);
  color: var(--color-paper-raised);
  padding: 0.72rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, transform 160ms ease-out;
}
.ds-btn-primary:hover {
  background: var(--color-cobalt);
  border-color: var(--color-cobalt);
}
.ds-btn-primary:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 3px;
}
.ds-btn-primary:active {
  transform: translateY(1px);
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid var(--color-line-strong);
  background: transparent;
  color: var(--color-ink);
  padding: 0.72rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, transform 160ms ease-out;
}
.ds-btn-secondary:hover {
  border-color: var(--color-ink);
  background: var(--color-paper-raised);
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 3px;
}
.ds-btn-secondary:active {
  transform: translateY(1px);
}

.ds-btn-danger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid color-mix(in srgb, var(--color-stamp) 45%, transparent);
  background: transparent;
  color: var(--color-stamp);
  padding: 0.72rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  line-height: 1;
  text-transform: uppercase;
  cursor: pointer;
  transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out, transform 160ms ease-out;
}
.ds-btn-danger:hover {
  background: var(--color-stamp);
  border-color: var(--color-stamp);
  color: var(--color-paper-raised);
}
.ds-btn-danger:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 3px;
}
.ds-btn-danger:active {
  transform: translateY(1px);
}

.ds-field-label {
  display: block;
  margin-bottom: 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-ink-soft);
}
.ds-field {
  width: 100%;
  border: 1px solid var(--color-line-strong);
  border-radius: var(--radius-sm);
  background: var(--color-paper-raised);
  padding: 0.7rem 0.8rem;
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  line-height: 1.5;
  transition: border-color 160ms ease-out, box-shadow 160ms ease-out;
}
.ds-field::placeholder {
  color: var(--color-ink-faint);
}
.ds-field:focus {
  border-color: var(--color-cobalt);
  box-shadow: 0 0 0 3px rgb(31 78 216 / 0.12);
  outline: none;
}
.ds-field-help {
  margin-top: 0.35rem;
  font-size: 0.8125rem;
  color: var(--color-ink-faint);
}

.ds-nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding-block: 0.25rem;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  color: var(--color-ink-soft);
  text-decoration: none;
  transition: color 160ms ease-out;
}
.ds-nav-link::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: var(--color-cobalt);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 200ms ease-out;
}
.ds-nav-link:hover,
.ds-nav-link[aria-current='page'] {
  color: var(--color-ink);
}
.ds-nav-link:hover::after,
.ds-nav-link[aria-current='page']::after {
  transform: scaleX(1);
}
.ds-nav-link:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 3px;
}

.ds-filter-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--color-line-strong);
  background: transparent;
  padding: 0.5rem 0.7rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--color-ink-soft);
  cursor: pointer;
  transition: background-color 160ms ease-out, border-color 160ms ease-out, color 160ms ease-out;
}
.ds-filter-chip:hover {
  border-color: var(--color-ink);
  color: var(--color-ink);
}
.ds-filter-chip[aria-pressed='true'] {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: var(--color-paper-raised);
}
.ds-filter-chip:focus-visible {
  outline: 2px solid var(--color-cobalt);
  outline-offset: 3px;
}

.ds-stamp {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 1px solid currentColor;
  padding: 0.28rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  box-shadow: 0 1px 0 rgb(21 24 27 / 0.08);
}
.ds-stamp-cobalt {
  color: var(--color-cobalt);
  background: var(--color-cobalt-wash);
}
.ds-stamp-manila {
  color: var(--color-manila-ink);
  background: var(--color-manila);
  border-color: var(--color-manila-deep);
}
.ds-stamp-stamp {
  color: var(--color-stamp);
  background: var(--color-stamp-wash);
}
.ds-stamp-success {
  color: var(--color-success);
  background: var(--color-success-wash);
}

.ds-ledger-row {
  display: grid;
  grid-template-columns: 2.5rem minmax(0, 1.6fr) minmax(10rem, 1fr);
  gap: 1rem 1.5rem;
  align-items: start;
  border-bottom: 1px solid var(--color-line);
  padding-block: 1.1rem;
  font-family: var(--font-sans);
  color: var(--color-ink);
}
.ds-ledger-index {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--color-cobalt);
}
.ds-ledger-index span {
  display: block;
  margin-top: 0.5rem;
  font-size: 0.5625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-faint);
}
.ds-ledger-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.ds-ledger-tag {
  display: inline-flex;
  border: 1px solid var(--color-cobalt);
  background: var(--color-cobalt-wash);
  padding: 0.28rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1;
  text-transform: uppercase;
  color: var(--color-cobalt);
}
.ds-ledger-tag-manila {
  border-color: var(--color-manila-deep);
  background: var(--color-manila);
  color: var(--color-manila-ink);
}
.ds-ledger-title {
  margin: 0.75rem 0 0;
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3vw, 2.6rem);
  font-weight: 600;
  line-height: 0.94;
  letter-spacing: -0.04em;
}
.ds-ledger-title a {
  color: inherit;
  text-decoration: none;
}
.ds-ledger-title a:hover {
  color: var(--color-cobalt);
}
.ds-ledger-summary {
  margin: 0.75rem 0 0;
  max-width: 42rem;
  font-size: 0.875rem;
  line-height: 1.75;
  color: var(--color-ink-soft);
}
.ds-ledger-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-ink-faint);
}
.ds-ledger-link {
  display: inline-flex;
  gap: 0.5rem;
  margin-top: 1.25rem;
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink);
  text-decoration: none;
}
.ds-ledger-link:hover {
  color: var(--color-cobalt);
}
.ds-ledger-plate {
  position: relative;
  min-height: 8rem;
  overflow: hidden;
  border: 1px solid var(--color-line);
  background: var(--color-paper-deep);
}
.ds-ledger-plate::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(to right, rgb(21 24 27 / 0.035) 1px, transparent 1px), linear-gradient(to bottom, rgb(21 24 27 / 0.035) 1px, transparent 1px);
  background-size: 18px 18px;
}
.ds-ledger-plate span {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 1;
  border: 1px solid var(--color-line-strong);
  background: var(--color-paper-raised);
  padding: 0.25rem 0.5rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-soft);
}

.ds-sheet {
  background: var(--color-paper-raised);
  border: 1px solid var(--color-line);
  box-shadow: 0 1px 0 rgb(21 24 27 / 0.06), 0 18px 40px -28px rgb(21 24 27 / 0.28);
  color: var(--color-ink);
  font-family: var(--font-sans);
}
.ds-sheet-header {
  border-bottom: 1px solid var(--color-line);
  background: var(--color-paper-deep);
  padding: 0.75rem 1rem;
}
.ds-sheet-header p {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-faint);
}
.ds-sheet-header h3 {
  margin: 0.25rem 0 0;
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.1;
}
.ds-sheet-body {
  padding: 1rem;
  font-size: 0.9375rem;
  line-height: 1.75;
  color: var(--color-ink-soft);
}

.ds-portrait {
  border: 1px solid var(--color-line);
  background: var(--color-paper-raised);
  font-family: var(--font-sans);
}
.ds-portrait-frame {
  display: grid;
  aspect-ratio: 4 / 5;
  place-items: center;
  background: var(--color-paper-deep);
  padding: 1.5rem;
  text-align: center;
}
.ds-portrait-placeholder {
  display: grid;
  width: 5rem;
  height: 5rem;
  place-items: center;
  border: 1px solid var(--color-ink);
  background: var(--color-ink);
  color: var(--color-paper-raised);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.18em;
}
.ds-portrait-frame p {
  margin-top: 1rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-faint);
}
.ds-portrait figcaption {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  border-top: 1px solid var(--color-line);
  background: var(--color-paper-deep);
  padding: 0.5rem 0.75rem;
  font-family: var(--font-mono);
  font-size: 0.5625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-ink-faint);
}
